 const table=x.hours.map(h=>`<tr><td>${esc(h.label)}</td><td>${h.temp===null?'—':h.temp.toFixed(1)+'°C'}</td><td>${h.humidity===null?'—':h.humidity+'%'}</td><td>${h.precip===null?'—':h.precip+' mm'}</td><td>${esc(h.phase)}</td></tr>`).join('');
