function groupFindings(items){const groups=new Map();for(const f of items){const k=f.status+'|'+f.code+'|'+f.phase;const old=groups.get(k);if(old)old.count++;else groups.set(k,{...f,count:1});}return [...groups.values()];}
// A new datasheet is checked for the existing job, not merely displayed in the sidebar.
function openCompareDialog(){
 if(!state.current?.job){addBubble('assistant','Run a job assessment first, then I can compare another paint with the same job.');return;}
 state.compareExtraction=null;state.compareApprovalToken=null;
 $('compare-file').value='';$('compare-text').value='';$('compare-review').innerHTML='';$('compare-review').classList.add('hidden');
 $('compare-confirm').checked=false;$('compare-confirm-row').classList.add('hidden');$('compare-run').disabled=true;
 $('compare-status').textContent='Choose the manufacturer PDF or paste the technical sheet.';
 $('compare-dialog').showModal();
}
async function extractComparison(){
 const button=$('compare-extract');button.disabled=true;
 $('compare-run').disabled=true;$('compare-confirm').checked=false;$('compare-confirm-row').classList.add('hidden');
 $('compare-review').classList.add('hidden');state.compareExtraction=null;state.compareApprovalToken=null;
 $('compare-status').textContent='Reading the manufacturer document…';
 try{
  const file=$('compare-file').files[0];let text=$('compare-text').value.trim(),fileBase64=null;
  if(file){if(file.size>1500000)throw Error('File must be under 1.5 MB.');
   if(/\.txt$/i.test(file.name))text=await file.text();
   else if(/\.pdf$/i.test(file.name))fileBase64=await toBase64(file);
   else throw Error('Choose a PDF or TXT file.');}
  if(!fileBase64&&text.length<120)throw Error('Provide a text-based PDF or at least 120 characters of technical text.');
  const data=await request('/api/extract',{text,fileBase64});
  state.compareExtraction=data.extraction;state.compareApprovalToken=data.approvalToken;state.compareDocumentId=data.documentId||null;
  const d=data.extraction;
  const facts=[['Application minimum',d.application_temp_min_c,'°C'],['Application maximum',d.application_temp_max_c,'°C'],['Drying minimum',d.drying_temp_min_c,'°C'],['Drying maximum',d.drying_temp_max_c,'°C'],['Rain-protection duration',d.rain_protection_hours,'h']];
  $('compare-review').innerHTML=`<h3>${esc(d.manufacturer||'Manufacturer')} · ${esc(d.product_name||'Unknown product')}</h3>${facts.map(([k,v,u])=>`<div class="compare-fact"><span>${esc(k)}</span><b>${esc(n(v,u))}</b></div>`).join('')}<details><summary>See original evidence (${d.source_evidence?.length||0})</summary><ul>${(d.source_evidence||[]).map(e=>`<li>${esc(e.field)}: “${esc(e.quote)}”</li>`).join('')||'<li>No supporting quotes extracted.</li>'}</ul></details>`;
  $('compare-review').classList.remove('hidden');$('compare-confirm-row').classList.remove('hidden');
  $('compare-status').textContent='Review the values and source quotations, then confirm below.';
 }catch(e){$('compare-status').textContent='Could not read this sheet: '+e.message;}
 finally{button.disabled=false;}
}
function updateCompareReady(){$('compare-run').disabled=!(state.compareApprovalToken&&$('compare-confirm').checked);}
async function checkAnotherPaint(){
 if(!state.current?.job||!state.compareApprovalToken||!$('compare-confirm').checked)return;
 const button=$('compare-run');button.disabled=true;$('compare-status').textContent='Checking this paint against real hourly weather…';
 try{
  const old=state.current, job={location:old.job.location,dateTime:old.job.dateTime,durationHours:old.job.durationHours,surface:old.job.surface,paintId:'uploaded',approvalToken:state.compareApprovalToken};
  const result=await request('/api/check',job);
  $('compare-dialog').close();state.current=result;state.job=job;
  addBubble('user',`Compare ${result.selected.paint.brand} ${result.selected.paint.name} with my job.`);
  addBubble('assistant',result.selected.conflicts.length?'I checked the uploaded paint against the live forecast. There is a weather conflict.':'I checked the uploaded paint against the live forecast. Here is the result.');
  saveAssessment(result,job);$('conversation-subtitle').textContent=`${result.forecast.location} · New forecast ${formatTime(result.forecast.fetchedAt,result.forecast.timezone)}`;
  renderReport(result);track('result_generated',result.selected.status);setChatReady(true);
  // Keep the approved upload in the job form so rescheduling can be checked without uploading again.
  state.extraction=state.compareExtraction;state.approvalToken=state.compareApprovalToken;state.documentId=state.compareDocumentId;
  if($('upload-section').classList.contains('hidden'))openUpload();
  renderExtraction(state.extraction);$('approve-extraction').checked=true;
  $('datasheet-file').value='';$('datasheet-text').value='';
  $('paint').value='';$('paint-note').textContent=`Last checked: ${result.selected.paint.brand} ${result.selected.paint.name} (uploaded datasheet).`;
  setNotice('Approved datasheet loaded. You can change the date and run another check.');
 }catch(e){$('compare-status').textContent='Comparison failed: '+e.message;button.disabled=false;}
}
