 section.innerHTML=`<div class="itinerary-header"><div><span class="section-kicker">PAINTING ITINERARY · LIVE WEATHER</span><h3>${esc(plan.paint)}</h3><p>${esc(plan.plannedCoats)}/${esc(plan.requestedCoats)} planned coat slots screened · ${esc(plan.location)}</p></div><button type="button" class="outline-btn itinerary-edit">Edit plan</button></div>${!plan.complete?'<div class="itinerary-alert">No complete weather-verified schedule for the requested work. Do not paint at blocked times.</div>':''}${days||'<p class="itinerary-summary">No coating slot passed the weather screen for the requested schedule.</p>'}${weatherDetails}${dimensions}${warningDetails}<p class="itinerary-note">${esc('Weather candidates are conditional; verify wall temperature, moisture, coating system and real drying before painting.')} ${plan.source?`<a href="${esc(plan.source)}" target="_blank" rel="noopener noreferrer">Official manufacturer source ↗</a>`:''}</p>`;
 $('conversation').append(section);
 section.querySelector('.itinerary-edit')?.addEventListener('click',()=>openPlanDialog());scrollBottom();
